types.01_SceIoStat:
typedef struct {
    u16 year; /* 0x0 */
    u16 month; /* 0x2 */
    u16 day; /* 0x4 */
    u16 hour; /* 0x6 */
    u16 minute; /* 0x8 */
    u16 second; /* 0xA */
    u32 microsecond; /* 0xC */
} ScePspDateTime;

/* 0x58 bytes */
struct SceIoStat {
    SceMode st_mode; /* 0x0 */
    u32 st_attr; /* 0x4 */
    SceOff st_size; /* 0x8 */
    ScePspDateTime st_ctime; /* 0x10 */
    ScePspDateTime st_atime; /* 0x20 */
    ScePspDateTime st_mtime; /* 0x30 */
    u32 st_private[6]; /* 0x40 */
};

types.SceIoDeviceEntry:
/* 1.00: 8 bytes (no d_userfd_count yet). */
struct SceIoDeviceEntry {
    SceIoDeviceTable *d_dp; /* 0x0 */
    void *d_private; /* 0x4 */
};

types.SceIoDeviceTable:
/* Driver descriptor passed to sceIoAddDrv (0x14 bytes). */
struct SceIoDeviceTable {
    char *dt_string; /* 0x0, device name */
    s32 dt_type; /* 0x4 */
    s32 dt_size; /* 0x8 */
    char *dt_desc; /* 0xC */
    SceIoDeviceFunction *dt_func; /* 0x10 */
};

types.SceIoDirent:
/* 0x160 bytes */
struct SceIoDirent {
    SceIoStat d_stat; /* 0x0 */
    char d_name[256]; /* 0x58 */
    void *d_private; /* 0x158 */
    s32 dummy; /* 0x15C */
};

